import {loadPlay,playAction} from './play-cloud.js?v=1';
import {currentMember} from './cloud.js?v=1';
import {createArcade} from './arcade-engine.js?v=1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MEMBERS=['Piggy','4010','Joey'];
export function setupActivities({home,notify}){
 const dialog=document.createElement('dialog');dialog.className='activity-dialog';dialog.setAttribute('aria-labelledby','activity-title');document.body.append(dialog);
 let state={ready:false,rows:[],wishes:[]},room=0,kind='',cleanup=()=>{},request=0,busy=false;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 async function sync(){try{state=await loadPlay();home()?.setAquariumColors(state.rows);}catch{notify('互动记录暂未同步，稍后再试')}}
 const row=()=>state.rows.find(r=>r.room_id===room)??{scores:{},fish_names:['小橘','小桃'],fish_colors:['#dfad69','#d99eae']};
 function shell(title,description){dialog.innerHTML=`<div class="activity-heading"><div><small>${MEMBERS[room]}的房间 / 互动家具</small><h2 id="activity-title">${title}</h2></div><button class="activity-close" aria-label="关闭互动">×</button></div><p class="activity-desc">${description}</p>${state.ready?'':'<p class="activity-offline">共享记录尚未开启。小游戏和观星可以体验；养鱼、排行与愿望保存需先执行 activities.sql。</p>'}<div id="activity-body"></div>`;dialog.querySelector('.activity-close').onclick=()=>dialog.close();return dialog.querySelector('#activity-body')}
 function loop(draw){let token=request,last=null,frameId;function frame(now){if(token!==request||!dialog.open)return;const dt=last===null?0:Math.min(.05,(now-last)/1000);last=now;if(!document.hidden)draw(now,dt);frameId=requestAnimationFrame(frame)}frameId=requestAnimationFrame(frame);return ()=>cancelAnimationFrame(frameId)}
 function canvas(body,label,height=320){const c=document.createElement('canvas');c.width=600;c.height=height;c.className='activity-canvas';c.setAttribute('aria-label',label);body.append(c);return c}
 async function action(name,value){if(busy||!state.ready)return false;busy=true;try{await playAction(room,name,value);await sync();return true}catch(error){notify(error.message||'保存未完成，请重试');return false}finally{busy=false}}
 function leaderboard(){return `<div class="activity-ranks"><h3>这台街机的最高分</h3>${MEMBERS.map((name,i)=>({name,score:row().scores?.[i]??0})).sort((a,b)=>b.score-a.score).map((p,i)=>`<div><span>${i+1}. ${p.name}</span><strong>${p.score}</strong></div>`).join('')}</div>`}
 function arcade(){const body=shell('接住今晚的星星','一分钟挑战。手机按住画面左右滑动；电脑用 ← → / A D，接住星星每颗得 10 分。');
  const c=canvas(body,'接星星游戏，使用方向键或拖动控制篮子'),ctx=c.getContext('2d');
  const controls=document.createElement('div');controls.className='activity-game-controls';controls.innerHTML='<span role="status" id="game-status">准备好接星星了吗？</span><button class="primary" id="game-start">开始挑战</button><button id="game-pause" hidden>暂停</button>';body.append(controls);
  const ranks=document.createElement('div');ranks.innerHTML=leaderboard();body.append(ranks);
  let game=createArcade(),playing=false,paused=false,saving=false,dragging=false,keys=new Set();const events=new AbortController(),signal=events.signal;
  const status=controls.querySelector('#game-status'),start=controls.querySelector('#game-start'),pause=controls.querySelector('#game-pause');
  function draw(now,dt){if(playing&&!paused){let delta=(keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0);game.move(game.state.x+delta*dt*.7);game.step(dt)}
   const s=game.state;ctx.fillStyle='#29243e';ctx.fillRect(0,0,600,320);ctx.fillStyle='#a797bb';for(let n=0;n<32;n++)ctx.fillRect(n*73%600,n*41%270,2,2);
   for(const item of s.items){ctx.fillStyle='#efce82';ctx.beginPath();for(let n=0;n<10;n++){const a=n*Math.PI/5-Math.PI/2,r=n%2?5:12,x=item.x*600+Math.cos(a)*r,y=item.y*320+Math.sin(a)*r;n?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill()}
   ctx.fillStyle='#b6a0cf';ctx.fillRect(s.x*600-37,280,74,18);ctx.strokeStyle='#e4d6ec';ctx.lineWidth=3;ctx.strokeRect(s.x*600-37,280,74,18);ctx.fillStyle='#f4e8ca';ctx.font='18px sans-serif';ctx.fillText(`得分 ${s.score}`,18,28);ctx.fillText(`${Math.ceil(s.remaining)} 秒`,515,28);
   if(!playing||paused){ctx.fillStyle='#f1e4cf';ctx.font='24px sans-serif';ctx.textAlign='center';ctx.fillText(paused?'暂停了，准备好再继续':s.ended?`接到了 ${s.score} 分`:'一起接住星星',300,155);ctx.textAlign='left'}
   if(playing&&s.ended){playing=false;pause.hidden=true;saving=true;start.disabled=true;status.textContent=`完成！${s.score} 分${state.ready?'，正在保存最高分…':'（本次成绩）'}`;const token=request;
    (async()=>{const saved=state.ready&&await action('score',{score:s.score});if(token!==request)return;saving=false;start.disabled=false;start.textContent='再玩一次';status.textContent=saved?`${s.score} 分 · 最高分已保存`:`${s.score} 分 · ${state.ready?'记录暂未保存':'本次成绩'}`;ranks.innerHTML=leaderboard()})();}
  }
  start.onclick=()=>{if(saving)return;game=createArcade();playing=true;paused=false;keys.clear();pause.hidden=false;pause.textContent='暂停';start.textContent='重新开始';status.textContent='接住星星，每颗 10 分'};
  pause.onclick=()=>{paused=!paused;keys.clear();pause.textContent=paused?'继续':'暂停'};
  function point(e){game.move((e.clientX-c.getBoundingClientRect().left)/c.getBoundingClientRect().width)}
  c.addEventListener('pointerdown',e=>{dragging=true;c.setPointerCapture(e.pointerId);point(e)},{signal});c.addEventListener('pointermove',e=>{if(dragging)point(e)},{signal});for(const event of ['pointerup','pointercancel'])c.addEventListener(event,()=>{dragging=false},{signal});
  document.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code)||e.target.matches('input,textarea,select'))return;e.preventDefault();keys.add(e.code)},{signal});document.addEventListener('keyup',e=>keys.delete(e.code),{signal});
  document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&playing){paused=true;pause.textContent='继续'}},{signal});window.addEventListener('blur',()=>{keys.clear();if(playing){paused=true;pause.textContent='继续'}},{signal});
  const stop=loop(draw);cleanup=()=>{stop();events.abort()};
 }
 function fishOptions(index){return [['#dfad69','金橘'],['#d99eae','樱粉'],['#87b2cd','雾蓝'],['#92b89b','薄荷']].map(([c,label])=>`<option value="${c}" ${(row().fish_colors?.[index]??['#dfad69','#d99eae'][index])===c?'selected':''}>${label}</option>`).join('')}
 function aquarium(){const body=shell('窗边的小鱼缸','两条小鱼一直好好的。家人都可以投喂，每十分钟一次；房间主人可以给它们起名字、选择颜色。');
  const c=canvas(body,'水草间游动的两条小鱼',280),ctx=c.getContext('2d');let food=[];
  const ui=document.createElement('div');ui.innerHTML=`<div class="fish-labels">${row().fish_names.map(n=>`<span>🐟 ${esc(n)}</span>`).join('')}</div><p class="activity-desc" id="fish-fed">${row().fed_at?'最近投喂：'+new Date(row().fed_at).toLocaleString('zh-CN'):'还没有投喂记录'}</p><button class="primary" id="fish-feed" ${state.ready?'':'disabled'}>投喂一点点</button>${currentMember().id===room?`<form id="fish-form" class="fish-form"><label>第一条<input name="first" value="${esc(row().fish_names[0])}" maxlength="12" required><select name="colorFirst" aria-label="第一条小鱼颜色">${fishOptions(0)}</select></label><label>第二条<input name="second" value="${esc(row().fish_names[1])}" maxlength="12" required><select name="colorSecond" aria-label="第二条小鱼颜色">${fishOptions(1)}</select></label><button ${state.ready?'':'disabled'}>保存鱼名</button></form>`:''}`;body.append(ui);
  ui.querySelector('#fish-feed').onclick=async()=>{const b=ui.querySelector('#fish-feed');b.disabled=true;const token=request;if(await action('feed')){if(token!==request)return;food=Array.from({length:12},(_,i)=>({x:110+i*30,y:5+i%3*8}));notify('小鱼来吃饭啦');ui.querySelector('#fish-fed').textContent='刚刚投喂过 · 十分钟后可再喂'}if(token===request)b.disabled=false};
  if(ui.querySelector('#fish-form'))ui.querySelector('#fish-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const names=[e.target.elements.first.value.trim(),e.target.elements.second.value.trim()];const token=request;if(await action('name',{names,colors:[e.target.elements.colorFirst.value,e.target.elements.colorSecond.value]})){if(token!==request)return;ui.querySelector('.fish-labels').innerHTML=names.map(n=>`<span>🐟 ${esc(n)}</span>`).join('');notify('小鱼有新名字啦')}if(token===request)b.disabled=false};
  cleanup=loop((now,dt)=>{ctx.fillStyle='#b4d8da';ctx.fillRect(0,0,600,280);ctx.fillStyle='#d4c6a6';ctx.fillRect(0,255,600,25);ctx.strokeStyle='#719980';ctx.lineWidth=5;for(let n=0;n<8;n++){ctx.beginPath();ctx.moveTo(35+n*22,258);ctx.quadraticCurveTo(5+n*22,190,35+n*22,155+n%3*20);ctx.stroke()}
   const time=reduced?0:now/1000;for(let i=0;i<2;i++){let x=300+Math.sin(time*.55+i*2.6)*180,y=130+Math.sin(time*.8+i)*35;if(food.length){x=240+i*90;y=75+i*30}ctx.save();ctx.translate(x,y);ctx.scale(Math.cos(time*.55+i*2.6)>=0?1:-1,1);ctx.fillStyle=row().fish_colors?.[i]??(i?'#d99eae':'#dfad69');ctx.beginPath();ctx.ellipse(0,0,28,13,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-23,0);ctx.lineTo(-44,-13);ctx.lineTo(-44,13);ctx.closePath();ctx.fill();ctx.fillStyle='#425b66';ctx.beginPath();ctx.arc(15,-3,3,0,7);ctx.fill();ctx.restore()}
   ctx.fillStyle='#ab8552';for(const grain of food){grain.y+=dt*30;ctx.fillRect(grain.x,grain.y,4,4)}food=food.filter(p=>p.y<160);ctx.strokeStyle='#e1f1f0';for(let n=0;n<6;n++){ctx.beginPath();ctx.arc(545,(250-n*38-time*14)%260,3,0,7);ctx.stroke()}
  });
 }
 function telescope(){const body=shell('今晚的星空','拖动星空转一转，点亮星查看星座。点“等一颗流星”，再把愿望留在你们的小家。');
  const c=canvas(body,'可拖动与点击的星空，星座也可通过下方按钮选择',330),ctx=c.getContext('2d');let shift=0,drag=null,meteor=0,selected='';
  const constellations=[{name:'北斗七星',desc:'七颗星连成勺子，是大熊座的一部分。',points:[[.12,.20],[.20,.26],[.29,.31],[.38,.39],[.46,.36],[.44,.53],[.34,.51]]},{name:'猎户座',desc:'腰带上三颗排列整齐的亮星，很容易辨认。',points:[[.63,.19],[.81,.22],[.67,.43],[.72,.44],[.77,.45],[.62,.68],[.83,.65]]}];
  const ui=document.createElement('div');ui.innerHTML=`<div class="star-choices">${constellations.map((s,i)=>`<button data-star="${i}">${s.name}</button>`).join('')}<button id="star-meteor">等一颗流星</button></div><p id="star-info" class="activity-desc" role="status">这是小家的原创星空示意，不代表实时天空。</p><form id="wish-form"><label for="wish-content">把愿望留给星星</label><textarea id="wish-content" maxlength="120" placeholder="希望下一次见面……" required></textarea><button class="primary" ${state.ready?'':'disabled'}>留下愿望</button></form><div id="wish-list" class="wish-list">${state.wishes.map(w=>`<p>✦ ${esc(w.content)}<small>${esc(MEMBERS[w.room_id])}房间的星空 · ${new Date(w.created_at).toLocaleDateString('zh-CN')}</small></p>`).join('')||'<p>还没有愿望，留下一颗属于你们的星星。</p>'}</div>`;body.append(ui);
  function select(i){selected=constellations[i].name;ui.querySelector('#star-info').textContent=selected+' · '+constellations[i].desc}
  ui.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>select(Number(b.dataset.star)));ui.querySelector('#star-meteor').onclick=()=>{meteor=1;ui.querySelector('#star-info').textContent='流星来啦，许个愿吧'};
  ui.querySelector('#wish-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),text=ui.querySelector('#wish-content').value.trim();b.disabled=true;const token=request;if(await action('wish',{content:text})){if(token!==request)return;notify('愿望留在星空里了');ui.querySelector('#wish-content').value='';const p=document.createElement('p');p.textContent='✦ '+text;ui.querySelector('#wish-list').prepend(p)}if(token===request)b.disabled=false};
  const events=new AbortController(),signal=events.signal;
  c.addEventListener('pointerdown',e=>{drag={start:e.clientX,last:e.clientX};c.setPointerCapture(e.pointerId)},{signal});c.addEventListener('pointermove',e=>{if(!drag)return;shift+=(e.clientX-drag.last)/c.getBoundingClientRect().width;shift=Math.max(-.06,Math.min(.06,shift));drag.last=e.clientX},{signal});c.addEventListener('pointerup',e=>{if(drag&&Math.abs(e.clientX-drag.start)<8){const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-shift,y=(e.clientY-r.top)/r.height;let best={distance:.07,index:-1};constellations.forEach((s,i)=>s.points.forEach(([sx,sy])=>{const d=Math.hypot(sx-x,sy-y);if(d<best.distance)best={distance:d,index:i}}));if(best.index>=0)select(best.index)}drag=null},{signal});c.addEventListener('pointercancel',()=>drag=null,{signal});
  const stop=loop((now,dt)=>{ctx.fillStyle='#24223d';ctx.fillRect(0,0,600,330);for(let n=0;n<85;n++){ctx.fillStyle=n%3?'#d9d4e5':'#f0d49f';ctx.globalAlpha=reduced?.75:.55+Math.sin(now/1700+n)*.25;ctx.fillRect((n*97%600)+shift*600,n*53%330,n%5===0?3:2,2)}ctx.globalAlpha=1;
   for(const s of constellations){ctx.strokeStyle=selected===s.name?'#d9b8e5':'#716b8e';ctx.lineWidth=1;ctx.beginPath();s.points.forEach(([x,y],i)=>i?ctx.lineTo((x+shift)*600,y*330):ctx.moveTo((x+shift)*600,y*330));ctx.stroke();for(const [x,y] of s.points){ctx.fillStyle='#fff0c4';ctx.beginPath();ctx.arc((x+shift)*600,y*330,4,0,7);ctx.fill()}}
   if(meteor>0){meteor=Math.max(0,meteor-dt*.5);const progress=1-meteor,x=90+progress*410,y=25+progress*160;ctx.strokeStyle='#efd7ad';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-55,y-20);ctx.lineTo(x,y);ctx.stroke();ctx.fillStyle='#fff3d3';ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill()}
  });cleanup=()=>{stop();events.abort()};
 }
 dialog.addEventListener('close',()=>{request++;cleanup();cleanup=()=>{}});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 async function open(type,roomId){request++;cleanup();room=roomId;kind=type;const token=request;await sync();if(token!==request)return;dialog.innerHTML='';if(!dialog.open)dialog.showModal();if(type==='arcade')arcade();else if(type==='aquarium')aquarium();else telescope()}
 const timer=setInterval(()=>{if(!dialog.open&&!busy)void sync()},10000);window.addEventListener('pagehide',()=>{request++;cleanup();clearInterval(timer)});void sync();return {open};
}
